-- ============================================================
-- ivr_executor.lua  —  ENRS IVR Flow Executor
-- Generated by ENRS IVR Builder. DO NOT EDIT MANUALLY.
-- Regenerate via: IVR Builder → Deploy button.
-- ============================================================

-- ── Configuration ──────────────────────────────────────────────
local API_BASE     = "http://127.0.0.1:4100/api/v1/internal"
local API_KEY      = "test"
local TTS_ENGINE   = "flite|kal"   -- engine|voice format (FreeSWITCH built-in fallback)
local PIPER_URL    = ""  -- empty = skip Piper, use FS TTS only
local MAX_STEPS    = 100            -- safety cap for loop detection
local HTTP_TIMEOUT = 8              -- curl timeout in seconds (node API calls)
local LOOKUP_TIMEOUT = 3            -- shorter timeout for the entry flow lookup (fail fast to failsafe)

-- ── JSON (cjson is usually bundled with mod_lua; fall back if not) ──

local json_ok, json = pcall(require, "cjson")
if not json_ok then
  freeswitch.consoleLog("WARN", "[ivr_executor] cjson not available, using minimal JSON fallback\n")
  json = {
    decode = function(str)
      local pos = 1
      local function skip() pos = str:match("^%s*()", pos) end
      local parse_val
      local function parse_str()
        local i, parts = pos + 1, {}
        while i <= #str do
          local c = str:sub(i,i)
          if c == '"' then pos = i+1; return table.concat(parts) end
          if c == '\\' then
            local e = str:sub(i+1,i+1)
            local esc = {['"']='"',['\\']= '\\',['/']= '/',['n']='\n',['r']='\r',['t']='\t',['b']='\b',['f']='\f'}
            if esc[e] then parts[#parts+1]=esc[e]; i=i+2
            elseif e=='u' then local h=str:sub(i+2,i+5); parts[#parts+1]=string.char(tonumber(h,16)%256); i=i+6
            else parts[#parts+1]=e; i=i+2 end
          else parts[#parts+1]=c; i=i+1 end
        end; return nil
      end
      local function parse_obj()
        pos=pos+1; local t={}; skip()
        if str:sub(pos,pos)=='}' then pos=pos+1; return t end
        while true do skip()
          if str:sub(pos,pos)~='"' then return nil end
          local k=parse_str(); skip()
          if str:sub(pos,pos)~=':' then return nil end
          pos=pos+1; t[k]=parse_val(); skip()
          local c=str:sub(pos,pos)
          if c=='}' then pos=pos+1; return t end
          if c~=',' then return nil end; pos=pos+1
        end
      end
      local function parse_arr()
        pos=pos+1; local t={}; skip()
        if str:sub(pos,pos)==']' then pos=pos+1; return t end
        while true do t[#t+1]=parse_val(); skip()
          local c=str:sub(pos,pos)
          if c==']' then pos=pos+1; return t end
          if c~=',' then return nil end; pos=pos+1
        end
      end
      parse_val = function()
        skip(); local c=str:sub(pos,pos)
        if c=='"' then return parse_str()
        elseif c=='{' then return parse_obj()
        elseif c=='[' then return parse_arr()
        elseif str:sub(pos,pos+3)=='true' then pos=pos+4; return true
        elseif str:sub(pos,pos+4)=='false' then pos=pos+5; return false
        elseif str:sub(pos,pos+3)=='null' then pos=pos+4; return nil
        else local n=str:match("^-?%d+%.?%d*[eE]?[+-]?%d*",pos)
          if n then pos=pos+#n; return tonumber(n) end
          return nil
        end
      end
      local ok, v = pcall(parse_val)
      return ok and v or nil
    end,
    encode = function(t)
      local parts = {}
      for k, v in pairs(t) do
        local val
        if type(v) == "string" then val = '"' .. v:gsub('"', '\\"') .. '"'
        elseif type(v) == "number" then val = tostring(v)
        elseif type(v) == "boolean" then val = tostring(v)
        end
        if val then parts[#parts+1] = '"' .. k .. '":' .. val end
      end
      return "{" .. table.concat(parts, ",") .. "}"
    end,
  }
end

-- ── HTTP via curl (io.popen) — no luasocket dependency ────────────

local function url_encode(s)
  return (tostring(s or "")):gsub("[^%w%-%.%_%~]", function(c)
    return string.format("%%%02X", string.byte(c))
  end)
end

local function http_request(method, url_path, body_obj, timeout_s)
  local url  = API_BASE .. url_path
  local tmo  = timeout_s or HTTP_TIMEOUT
  local cmd
  if method == "GET" then
    cmd = string.format(
      'curl -s -m %d -H "X-Internal-Key: %s" "%s" 2>/dev/null',
      tmo, API_KEY, url)
  else
    local body_str = body_obj and json.encode(body_obj) or "{}"
    local safe_body = body_str:gsub("'", "'\\''")
    cmd = string.format(
      "curl -s -m %d -X %s -H 'Content-Type: application/json' -H 'X-Internal-Key: %s' -d '%s' '%s' 2>/dev/null",
      tmo, method, API_KEY, safe_body, url)
  end

  local h    = io.popen(cmd)
  local body = (h and h:read("*a")) or ""
  if h then h:close() end

  if body == "" then
    freeswitch.consoleLog("WARN",
      "[ivr_executor] " .. method .. " " .. url_path .. " => empty response\n")
    return nil
  end
  local ok, data = pcall(json.decode, body)
  if not ok or data == nil then
    freeswitch.consoleLog("ERR", "[ivr_executor] JSON parse error for " .. url_path .. ": " .. tostring(data) .. "\n")
    return nil
  end
  return data
end

local function get(p)      return http_request("GET",  p, nil)     end
local function get_t(p, t) return http_request("GET",  p, nil, t)  end
local function post(p, b)  return http_request("POST", p, b)       end

-- Internal POST with a caller-supplied curl timeout (seconds). Used by the
-- rest_api node: the backend proxy performs the real (credentialed) external
-- call and enforces its own shorter timeout, so this internal call just needs
-- a slightly larger ceiling. Same X-Internal-Key contract as http_request.
local function internal_post_t(url_path, body_obj, timeout_s)
  local url       = API_BASE .. url_path
  local body_str  = body_obj and json.encode(body_obj) or "{}"
  local safe_body = body_str:gsub("'", "'\\''")
  local cmd = string.format(
    "curl -s -m %d -X POST -H 'Content-Type: application/json' -H 'X-Internal-Key: %s' -d '%s' '%s' 2>/dev/null",
    timeout_s, API_KEY, safe_body, url)
  local h    = io.popen(cmd)
  local resp = (h and h:read("*a")) or ""
  if h then h:close() end
  if resp == "" then return nil end
  local ok, data = pcall(json.decode, resp)
  if not ok or data == nil then return nil end
  return data
end

-- ── Variable interpolation ───────────────────────────────────────

local function interp(s, str)
  if not str then return "" end
  return (str:gsub("${([^}]+)}", function(k)
    return s:getVariable(k) or ""
  end))
end

-- no_api_expand: applied where text becomes a SIPCommunication application argument
-- (transfer, built-in TTS, playback). The engine expands ${...} there, and the API
-- form "${name args}" / "${name(args)}" RUNS a command, so a caller-supplied value
-- (caller name, an API response) must not be able to form one. Plain ${variable}
-- references are left exactly as they were, so existing flows behave the same.
local function no_api_expand(v)
  local out = tostring(v or "")
  local changed = true
  while changed do
    changed = false
    local i = 1
    while true do
      local a = out:find("${", i, true)
      if not a then break end
      local b = out:find("}", a + 2, true)
      local inner = b and out:sub(a + 2, b - 1) or out:sub(a + 2)
      if inner:find("[%s%(%$]") then
        out = out:sub(1, a - 1) .. out:sub(a + 2)   -- drop the "${": the text becomes inert
        changed = true
      else
        i = a + 2
      end
    end
  end
  return out
end

-- The number this call was routed on, captured before any node runs. Nodes can
-- change destination_number; this local cannot be changed by a flow.
local CALL_NUMBER = ""

local PROTECTED_VAR_NAMES = {}
for _, n in ipairs({ "uuid", "call_uuid", "api_hangup_hook", "api_reporting_hook", "api_after_bridge", "exec_after_bridge_app", "exec_after_bridge_arg" }) do PROTECTED_VAR_NAMES[n] = true end
local PROTECTED_VAR_PREFIXES = { "api_on_", "execute_on_", "bridge_pre_execute_" }
local function is_protected_var(name)
  local n = string.lower(tostring(name or ""))
  if PROTECTED_VAR_NAMES[n] then return true end
  for _, p in ipairs(PROTECTED_VAR_PREFIXES) do if n:sub(1, #p) == p then return true end end
  return false
end

-- set_var: every flow-controlled variable write goes through here.
local function set_var(s, name, value)
  if is_protected_var(name) then
    freeswitch.consoleLog("ERR", "[ivr_executor] refused to set protected variable " .. tostring(name) .. "\n")
    return false
  end
  s:setVariable(name, value)
  return true
end

-- ── Audio resolution ─────────────────────────────────────────────

-- Get sounds_dir from running FreeSWITCH at startup
local _api       = freeswitch.API()
local SOUNDS_DIR = _api:execute("global_getvar", "sounds_dir") or "/usr/share/freeswitch/sounds"

local function resolve_audio(uri)
  if not uri or uri == "" then return nil end
  if uri:sub(1,7) == "/media/" then
    return no_api_expand(SOUNDS_DIR .. "/enrs/" .. uri:sub(8))
  end
  return no_api_expand(uri)
end

-- ── TTS speak (Piper-first, FreeSWITCH built-in fallback) ─────────

-- Per-call sequence counter for unique TTS filenames within one call session.
-- mod_lua creates a fresh Lua state per call, so this resets naturally.
local _tts_seq = 0

-- Minimal, correct JSON string escaper (quotes, backslashes, control chars
-- incl. newlines) so multi-line TTS text yields valid JSON. Replaces the old
-- string.format("%q",...) which emitted backslash+newline (invalid JSON) for
-- multi-line input and silently defeated line-based sentence pauses.
local function json_escape(v)
  local s = tostring(v or "")
  return (s:gsub(".", function(c)
    local b = string.byte(c)
    if c == '"' then return '\\"'
    elseif c == '\\' then return '\\\\'
    elseif b == 10 then return '\\n'
    elseif b == 13 then return '\\r'
    elseif b == 9 then return '\\t'
    elseif b < 32 then return string.format('\\u%04X', b)
    else return c end
  end))
end

-- speak(s, text[, sentence_silence_ms]) — synthesize via Piper and play.
-- sentence_silence_ms is an optional per-node pause override; when nil the
-- Piper service applies its PIPER_SENTENCE_SILENCE_MS default.
local function speak(s, text, sentence_silence_ms)
  if not text or text == "" then return end
  if PIPER_URL ~= "" then
    local rec_base  = _api:execute("global_getvar", "recordings_dir") or "/var/lib/freeswitch/recordings"
    local tts_dir   = rec_base .. "/ivr_tts"
    os.execute("mkdir -p '" .. tts_dir .. "'")
    _tts_seq = _tts_seq + 1
    local call_uuid = s:getVariable("uuid") or "u"
    local wav_path  = tts_dir .. "/tts_" .. call_uuid .. "_" .. _tts_seq .. ".wav"
    -- Build a valid JSON body via json_escape (handles newlines/quotes) and
    -- pass the optional per-node sentence pause through to the Piper service.
    local sil = ""
    if sentence_silence_ms ~= nil and tonumber(sentence_silence_ms) ~= nil then
      sil = ',"sentence_silence_ms":' .. tostring(math.floor(tonumber(sentence_silence_ms)))
    end
    local body      = '{"text":"' .. json_escape(text) .. '","sample_rate":8000' .. sil .. '}'
    local safe_b    = body:gsub("'", "'\\''")  -- escape ' for shell single-quote context
    local cmd = string.format(
      "curl -sf -m 25 -X POST -H 'Content-Type: application/json' -d '%s' '%s/synthesize' -o '%s' && echo piper_ok",
      safe_b, PIPER_URL, wav_path)
    local h   = io.popen(cmd .. " 2>/dev/null")
    local out = h and h:read("*a") or ""
    if h then h:close() end
    local fsize = 0
    local fh = io.open(wav_path, "rb")
    if fh then fsize = fh:seek("end") or 0; fh:close() end
    if out:find("piper_ok", 1, true) and fsize > 100 then
      s:streamFile(wav_path)
      os.remove(wav_path)
      return
    end
    freeswitch.consoleLog("ERR",
      "[ivr_executor] Piper TTS failed (url=" .. PIPER_URL .. " size=" .. fsize .. ") — node will be silent\n")
    os.remove(wav_path)
    return  -- do not fall through to FreeSWITCH TTS; Piper is the configured engine
  end
  s:execute("speak", TTS_ENGINE .. "|" .. no_api_expand(text))
end

-- speak_to_file(s, text) — render TTS to a wav FILE and return its path (no
-- playback, no cleanup). Used by barge-in collection, which needs a file to
-- hand to playAndGetDigits. Returns nil when Piper is unavailable or fails,
-- so the caller can fall back to non-barge collection. Caller removes the file.
local function speak_to_file(s, text)
  if not text or text == "" then return nil end
  if PIPER_URL == "" then return nil end
  local rec_base = _api:execute("global_getvar", "recordings_dir") or "/var/lib/freeswitch/recordings"
  local tts_dir  = rec_base .. "/ivr_tts"
  os.execute("mkdir -p '" .. tts_dir .. "'")
  _tts_seq = _tts_seq + 1
  local call_uuid = s:getVariable("uuid") or "u"
  local wav_path  = tts_dir .. "/tts_" .. call_uuid .. "_" .. _tts_seq .. ".wav"
  local body   = '{"text":"' .. json_escape(text) .. '","sample_rate":8000}'
  local safe_b = body:gsub("'", "'\\''")
  local cmd = string.format(
    "curl -sf -m 25 -X POST -H 'Content-Type: application/json' -d '%s' '%s/synthesize' -o '%s' && echo piper_ok",
    safe_b, PIPER_URL, wav_path)
  local h   = io.popen(cmd .. " 2>/dev/null")
  local out = h and h:read("*a") or ""
  if h then h:close() end
  local fsize = 0
  local fh = io.open(wav_path, "rb")
  if fh then fsize = fh:seek("end") or 0; fh:close() end
  if out:find("piper_ok", 1, true) and fsize > 100 then return wav_path end
  os.remove(wav_path)
  return nil
end

-- ── play_prompt: language-neutral prompt dispatcher (additive) ─────
-- Reuses resolve_audio + speak + interp. Returns true when the configured
-- prompt was played (or source=="none"), false on a PLAYBACK/PROMPT failure.
--
-- R4 OBSERVABILITY LIMITATION (accurate scope of the boolean return):
--   DETECTED  -> returns false for configuration-shaped failures only:
--                empty/missing audio URI, empty TTS text, unknown source.
--   NOT DETECTED (returns true): a missing physical file after /media path
--                mapping, s:streamFile runtime failure, Piper unavailable,
--                Piper HTTP failure, or TTS synthesis failure — because
--                speak() intentionally returns no status (left unchanged).
--                speak() logs its own ERR for Piper failures; play_prompt
--                cannot reflect that in its return value.
-- In ALL cases a prompt failure is a PROMPT failure ONLY: it is played as a
-- separate step from digit collection, so it never consumes a DTMF attempt
-- and callers must NOT convert it into a caller-input failure (e.g.
-- no_input). No user-facing text lives here.
local function play_prompt(s, src, audio_url, text)
  src = src or "none"
  if src == "none" then return true end
  if src == "audio" then
    local f = resolve_audio(audio_url)
    if f then s:streamFile(f); return true end
    freeswitch.consoleLog("ERR", "[ivr_executor] play_prompt: source=audio but audio unresolvable (audio_url=" .. tostring(audio_url) .. ")\n")
    return false
  end
  if src == "tts" then
    local t = interp(s, text)
    if t == nil or t == "" then
      freeswitch.consoleLog("WARN", "[ivr_executor] play_prompt: source=tts but text is empty\n")
      return false
    end
    speak(s, t)
    return true
  end
  freeswitch.consoleLog("WARN", "[ivr_executor] play_prompt: unknown source_type=" .. tostring(src) .. "\n")
  return false
end

-- ── Variable-insertion usability + fallback (additive) ───────────
-- Used by exec_say when a fallback_text is configured. interp(), speak()
-- and resolve_audio() are left byte-for-byte unchanged; these helpers sit
-- alongside them and reuse interp() as-is.
-- Carrier-sent non-name tokens (lowercased) treated as "no usable value".
-- These are internal MATCHING tokens, never user-facing text.
local UNUSABLE_VALUES = {
  [""] = true, ["anonymous"] = true, ["unknown"] = true,
  ["unavailable"] = true, ["restricted"] = true, ["private"] = true,
  ["private number"] = true, ["caller id blocked"] = true,
}
local function value_usable(v)
  if v == nil then return false end
  local t = v:gsub("^%s+", ""):gsub("%s+$", "")
  if t == "" then return false end
  if UNUSABLE_VALUES[t:lower()] then return false end
  return true
end
-- true when every ${var} referenced in text resolves to a usable value;
-- text with no placeholders is always resolvable.
local function all_vars_usable(s, text)
  if not text then return false end
  local ok = true
  for name in text:gmatch("${([^}]+)}") do
    if not value_usable(s:getVariable(name)) then ok = false end
  end
  return ok
end
-- comma-separated list of ${var} names referenced in text — for logging
-- ONLY the names, NEVER the resolved values (governance O-7).
local function vars_referenced(text)
  local names = {}
  if text then for n in text:gmatch("${([^}]+)}") do names[#names + 1] = n end end
  return table.concat(names, ",")
end
-- Pick primary when all its referenced vars are usable, else the fallback.
-- Returns (rendered_text, used_fallback_boolean).
local function render_with_fallback(s, primary, fallback)
  if fallback ~= nil and fallback ~= "" and not all_vars_usable(s, primary) then
    return interp(s, fallback), true
  end
  return interp(s, primary), false
end

-- ── Node executors (generated from nodeTypes/registry.js) ─────────

local function exec_play(s, node)
  local f
  if node.audio_source_type == "variable" then
    -- Dynamic source: resolve the file path from a session variable.
    -- The variable is written by a Record node or set_variable node
    -- earlier in the flow (e.g. recorded_file_path).
    local var_name = node.audio_variable or "recorded_file_path"
    local var_val  = no_api_expand(s:getVariable(var_name) or "")
    f = var_val ~= "" and var_val or nil
    if not f then
      freeswitch.consoleLog("WARN", "[ivr_executor] play: variable '" .. var_name .. "' is empty — skipping audio\n")
    end
  else
    -- Static source: path from the Media Library, resolved via resolve_audio().
    f = resolve_audio(node.audio_url)
  end
  if f then s:streamFile(f) end
  return node.next
end

local function exec_say(s, node)
  -- Legacy path: unchanged behavior when no fallback_text is configured.
  if node.fallback_text == nil or node.fallback_text == "" then
    speak(s, interp(s, node.text), node.sentence_silence_ms)
    return node.next
  end
  -- New path: personalize with graceful fallback when a referenced variable
  -- (e.g. caller_id_name) has no usable value. Logs referenced var NAMES and a
  -- fallback-used flag only — never the resolved value (governance O-7).
  local text, used_fallback = render_with_fallback(s, node.text, node.fallback_text)
  freeswitch.consoleLog("INFO", "[ivr_executor] say: vars=" .. vars_referenced(node.text) .. " fallback_used=" .. tostring(used_fallback) .. "\n")
  speak(s, text, node.sentence_silence_ms)
  return node.next
end

local function exec_gather(s, node)
  local br = node.branches or {}

  -- ─────────────────────────────────────────────────────────────────────
  -- LEGACY PATH — executed verbatim when the designer has NOT opted into the
  -- configurable retry model (node.max_attempts is absent). Behavior, prompts,
  -- native 3-try retry, and routing are IDENTICAL to the pre-existing node.
  -- Do not reinterpret legacy flows.
  -- ─────────────────────────────────────────────────────────────────────
  -- Legacy applies ONLY to nodes with neither max_attempts nor an explicit
  -- retry_mode. New retry_mode nodes (internal/external) skip legacy entirely.
  if node.max_attempts == nil and node.retry_mode == nil then
    local min_d   = node.min_digits          or 1
    local max_d   = node.max_digits          or 1
    local timeout = (node.timeout_seconds    or 10) * 1000
    local idt     = (node.inter_digit_timeout or 2) * 1000
    local terms   = node.terminators or ""
    local digits  = ""
    local src     = node.prompt_source_type or "tts"

    if src == "audio" then
      local pf = resolve_audio(node.prompt_audio_url)
      if pf then
        digits = s:playAndGetDigits(min_d, max_d, 3, timeout, terms, pf, "", "[0-9#*]+", "", idt) or ""
      else
        freeswitch.consoleLog("ERR", "[ivr_executor] gather: prompt_source_type=audio but audio_url is missing/unresolvable (audio_url=" .. tostring(node.prompt_audio_url) .. ")\n")
        -- Source configuration error — no cross-type fallback. Collect digits without prompt.
        digits = s:getDigits(max_d, terms, timeout) or ""
      end
    else
      -- TTS path: manual retry loop enforces min_d (getDigits has no min parameter).
      local tries = 3
      while tries > 0 and s:ready() do
        local pt = interp(s, node.prompt_text)
        if pt ~= "" then speak(s, pt) end
        local d = s:getDigits(max_d, terms, timeout) or ""
        if d == "" then break end
        if #d >= min_d then digits = d; break end
        tries = tries - 1
        if tries > 0 then speak(s, "Please enter at least " .. tostring(min_d) .. " digit" .. (min_d > 1 and "s" or "") .. ".") end
      end
    end

    set_var(s, node.variable_name or "gather_result", digits)

    -- Explicit timeout route: empty string means no input was received.
    -- Falls through to _default when no timeout branch is wired.
    if digits == "" then
      return br["timeout"] or br["_default"]
    end
    -- Input received: match exact branch, then _default (catch-all), then invalid.
    return br[digits] or br["_default"] or br["invalid"]
  end

  -- ─────────────────────────────────────────────────────────────────────
  -- NEW CONFIGURABLE PATH — designer set node.max_attempts. Failure reasons
  -- are distinguished (no_input / invalid_length / invalid_option / VALID);
  -- each reason has its own optional retry toggle and its own configured
  -- prompt source (tts / audio / none). ZERO user-facing text is hardcoded:
  -- every played prompt comes from node configuration via play_prompt().
  -- ─────────────────────────────────────────────────────────────────────
  local min_d   = node.min_digits       or 1
  local max_d   = node.max_digits       or 1
  local timeout = (node.timeout_seconds or 5) * 1000
  -- Inter-digit timeout: getDigits accepts an optional 4th arg (ms allowed
  -- between consecutive digits). Same field/default as the legacy audio path.
  local idt     = (node.inter_digit_timeout or 2) * 1000
  local terms   = node.terminators or ""
  local var     = node.variable_name or "gather_result"

  -- Barge-in: stop the prompt on the first DTMF and collect it. Default ON;
  -- accepts boolean true / string "yes". When OFF, the prompt plays fully first.
  local allow_barge = node.allow_barge_in
  if allow_barge == nil then allow_barge = true else allow_barge = (allow_barge == true or allow_barge == "yes") end

  -- collect(psrc,purl,ptext) → raw digits string. With barge on, the prompt is
  -- played by playAndGetDigits (first DTMF stops it, remaining digits collected
  -- with the inter-digit timeout, terminators respected) for BOTH audio and TTS
  -- (TTS rendered to a wav first). min is fixed at 1 and the regex is permissive
  -- so the RAW digits are returned — the caller's own #d<min_d check still
  -- classifies no_input / invalid_length / invalid_option exactly as before.
  -- Falls back to getDigits (no barge) when there is no playable prompt
  -- (source=none / TTS render unavailable) or when barge is off.
  local function collect(psrc, purl, ptext)
    psrc = psrc or "none"
    if allow_barge then
      local file
      if psrc == "audio" then
        file = resolve_audio(purl)
      elseif psrc == "tts" then
        local t = interp(s, ptext)
        if t and t ~= "" then file = speak_to_file(s, t) end
      end
      if file then
        local d = s:playAndGetDigits(1, max_d, 1, timeout, terms, file, "", "[0-9*#]+", "", idt) or ""
        if psrc == "tts" then os.remove(file) end
        return d
      end
      return s:getDigits(max_d, terms, timeout, idt) or ""
    end
    play_prompt(s, psrc, purl, ptext)
    return s:getDigits(max_d, terms, timeout, idt) or ""
  end

  -- ─────────────────────────────────────────────────────────────────────
  -- EXTERNAL mode — exactly ONE collection attempt; failure handling is the
  -- graph's responsibility. Valid input → success (digit branch, or _default
  -- for a completed multi-digit collection = Continue). No input → "timeout"
  -- branch. Invalid (short, or complete-but-unmapped) → "invalid" branch.
  -- No retry loop, no max_attempts_exceeded. _default keeps its success meaning.
  -- ─────────────────────────────────────────────────────────────────────
  if node.retry_mode == "external" then
    local d = collect(node.prompt_source_type, node.prompt_audio_url, node.prompt_text)
    set_var(s, var, d)
    if d == "" then
      freeswitch.consoleLog("INFO", "[ivr_executor] gather(external): var=" .. var .. " reason=no_input → timeout\n")
      return br["timeout"]
    elseif #d < min_d then
      freeswitch.consoleLog("INFO", "[ivr_executor] gather(external): var=" .. var .. " reason=invalid_length → invalid\n")
      return br["invalid"]
    end
    local target = br[d] or br["_default"]
    if target then
      freeswitch.consoleLog("INFO", "[ivr_executor] gather(external): var=" .. var .. " reason=VALID\n")
      return target
    end
    freeswitch.consoleLog("INFO", "[ivr_executor] gather(external): var=" .. var .. " reason=invalid_option → invalid\n")
    return br["invalid"]
  end

  -- R5: normalize a value read from RAW JSONB to a whole number >= 1. This is
  -- DEFENSIVE handling for malformed graph JSON only (fractions floored, <1 and
  -- non-numeric coerced to 1) — it is NOT a product default. Zod/publish
  -- validation remains authoritative for normal published flows (int 1-10).
  -- The legacy gate above is on ABSENCE of max_attempts, so this runs only when
  -- max_attempts was explicitly provided.
  local max_att = math.floor(tonumber(node.max_attempts) or 1)
  if max_att < 1 then max_att = 1 end

  -- Retry policy — configuration-driven; nil-safe defaults because raw JSONB
  -- config is read at call time (Zod defaults are not persisted). Accepts a
  -- boolean true/false or the string "yes"/"no" from the designer.
  local retry_ni = node.retry_on_no_input
  if retry_ni == nil then retry_ni = true else retry_ni = (retry_ni == true or retry_ni == "yes") end
  local retry_il = node.retry_on_invalid_length
  if retry_il == nil then retry_il = true else retry_il = (retry_il == true or retry_il == "yes") end
  local retry_io = node.retry_on_invalid_option
  if retry_io == nil then retry_io = false else retry_io = (retry_io == true or retry_io == "yes") end

  -- Re-prompt pause (ms) — a natural gap so retries do not sound rushed.
  -- Nodes saved before this field existed default to 700 (?? 700). Played as an
  -- interruptible silence_stream so a keypress during the pause still barges.
  local pause_ms = tonumber(node.reprompt_pause_ms)
  if pause_ms == nil then pause_ms = 700 end
  if pause_ms < 0 then pause_ms = 0 end
  local function reprompt_pause()
    if pause_ms > 0 and s:ready() then
      s:execute("playback", "silence_stream://" .. math.floor(pause_ms))
    end
  end

  local retry_src, retry_url, retry_text, retry_replay
  local attempt = 0

  while attempt < max_att and s:ready() do
    attempt = attempt + 1

    -- Attempt 1 plays the initial MENU prompt. Later attempts play the
    -- reason-specific EXCEPTION prompt (chosen at the end of the previous attempt)
    -- and then — when that reason's replay_menu is enabled (default ON) — REPLAY
    -- the same single menu prompt (node.prompt_*) before collecting again. Menu
    -- prompt and exception prompt are distinct concepts; the menu is defined once
    -- and reused (no second menu-prompt slot).
    -- Collection point. The MENU prompt is played by collect() so the first
    -- DTMF barges in (prompt + collect unified). On retries the EXCEPTION prompt
    -- is played first (interruptible; a digit pressed during it carries into the
    -- following collect), then the pause, then the menu replay / collection.
    local d
    if attempt == 1 then
      d = collect(node.prompt_source_type, node.prompt_audio_url, node.prompt_text)
    else
      -- Start of a retry iteration: flush stale/early DTMF BEFORE the exception
      -- prompt so leftover keypresses can't trigger an instant repeat-invalid.
      -- (Not flushed after — digits pressed during the menu are kept for barge.)
      s:flushDigits()
      play_prompt(s, retry_src, retry_url, retry_text)   -- exception prompt
      reprompt_pause()                                    -- breath before the menu
      if retry_replay then
        d = collect(node.prompt_source_type, node.prompt_audio_url, node.prompt_text)
      else
        d = collect("none", nil, nil)                     -- no menu replay; collect only
      end
    end
    set_var(s, var, d)

    local reason
    if d == "" then
      reason = "no_input"
    elseif #d < min_d then
      reason = "invalid_length"
    else
      -- Complete, well-formed entry: VALID if it maps to a branch/_default.
      local target = br[d] or br["_default"]
      if target then
        freeswitch.consoleLog("INFO", "[ivr_executor] gather: var=" .. var .. " attempt=" .. attempt .. "/" .. max_att .. " reason=VALID\n")
        return target
      end
      reason = "invalid_option"
    end

    freeswitch.consoleLog("INFO", "[ivr_executor] gather: var=" .. var .. " attempt=" .. attempt .. "/" .. max_att .. " reason=" .. reason .. "\n")

    local do_retry
    if reason == "no_input" then do_retry = retry_ni
    elseif reason == "invalid_length" then do_retry = retry_il
    else do_retry = retry_io end

    if not do_retry then
      -- Route immediately on this reason (reserved key, then legacy fallbacks).
      return br[reason] or br["_default"] or br["timeout"] or br["invalid"]
    end

    -- Prepare the reason-specific EXCEPTION prompt for the NEXT attempt, plus
    -- whether to replay the menu after it. replay_menu defaults ON (nil → true);
    -- accepts boolean true / string "yes". Set false / "no" for exception-only.
    retry_src  = node[reason .. "_source_type"]
    retry_url  = node[reason .. "_audio_url"]
    retry_text = node[reason .. "_text"]
    local rm   = node[reason .. "_replay_menu"]
    retry_replay = (rm == nil or rm == true or rm == "yes")
  end

  -- Attempts exhausted — brief pause, then optional terminal prompt + branch.
  reprompt_pause()
  play_prompt(s, node.max_attempts_exceeded_source_type,
                 node.max_attempts_exceeded_audio_url,
                 node.max_attempts_exceeded_text)
  freeswitch.consoleLog("INFO", "[ivr_executor] gather: attempts exhausted (" .. max_att .. ") var=" .. var .. "\n")
  return br["max_attempts_exceeded"] or br["timeout"] or br["_default"]
end

local function exec_condition(s, node)
  local op  = node.operator or "=="
  local val = s:getVariable(node.variable or "") or ""
  local exp = interp(s, node.expected_value) or ""
  local ok  = false

  if     op == "==" then
    ok = (val == exp)
  elseif op == "!=" then
    ok = (val ~= exp)
  elseif op == "contains" then
    ok = (val:find(exp, 1, true) ~= nil)
  elseif op == "starts_with" then
    ok = (val:sub(1, #exp) == exp)
  elseif op == "ends_with" then
    ok = #val >= #exp and val:sub(-#exp) == exp
  elseif op == "exists" then
    -- true when the variable is set to a non-empty string
    ok = (val ~= "")
  elseif op == "not_exists" then
    ok = (val == "")
  elseif op == "gt" then
    local n, e = tonumber(val), tonumber(exp)
    ok = (n ~= nil and e ~= nil and n > e)
  elseif op == "gte" then
    local n, e = tonumber(val), tonumber(exp)
    ok = (n ~= nil and e ~= nil and n >= e)
  elseif op == "lt" then
    local n, e = tonumber(val), tonumber(exp)
    ok = (n ~= nil and e ~= nil and n < e)
  elseif op == "lte" then
    local n, e = tonumber(val), tonumber(exp)
    ok = (n ~= nil and e ~= nil and n <= e)
  elseif op == "ens_pin_valid" then
    -- PIN check goes through /ens/verify-pin ONLY — it is the single
    -- source of truth for pin_required + correctness (handles "no PIN
    -- configured -> always authorized" internally). /ens/lookup never
    -- reads a pin query param at all; the raw PIN is never echoed back
    -- by lookup, matching the documented contract in CLAUDE.md.
    local dest = exp ~= "" and exp or s:getVariable("destination_number") or ""
    local verify = post("/ens/verify-pin", { trigger_number = dest, pin = val })
    if verify and verify.authorized then
      local lookup = get("/ens/lookup?number=" .. url_encode(dest) .. "&ivr_number=" .. url_encode(CALL_NUMBER))
      if lookup and lookup.success and lookup.data then
        s:setVariable("ens_configuration_id", tostring(lookup.data.configuration_id))
        s:setVariable("ens_blast_clid",       lookup.data.blast_clid or "")
      end
      ok = true
    end
  elseif op == "time_of_day" then
    -- expected_value format: "HHMM-HHMM" e.g. "0900-1700"
    local now_hhmm = tonumber(os.date("%H%M")) or 0
    local s_part, e_part = exp:match("^(%d%d%d%d)-(%d%d%d%d)$")
    if s_part and e_part then
      local start_n = tonumber(s_part) or 0
      local end_n   = tonumber(e_part) or 2359
      if start_n <= end_n then
        ok = (now_hhmm >= start_n and now_hhmm < end_n)
      else
        -- overnight range e.g. 2200-0600
        ok = (now_hhmm >= start_n or now_hhmm < end_n)
      end
    end
  elseif op == "day_of_week" then
    -- expected_value: comma-separated day numbers 0=Sun … 6=Sat
    local today = tonumber(os.date("%w")) or -1
    for d in exp:gmatch("%d+") do
      if tonumber(d) == today then ok = true; break end
    end
  elseif op == "ens_callback_valid" then
    -- expected_value carries the reply_clid the caller dialed in on —
    -- matches GET /ens/callbacks/authorize?reply_clid=&caller= exactly.
    local reply_clid = exp ~= "" and exp or ""
    local caller = s:getVariable("caller_id_number") or ""
    local d = get("/ens/callbacks/authorize?reply_clid=" .. url_encode(reply_clid) .. "&caller=" .. url_encode(caller))
    if d and d.authorized then
      s:setVariable("ens_notification_uuid", d.notification_uuid or "")
      s:setVariable("ens_recording_file",    d.recording_file or "")
      s:setVariable("ens_delivery_id",       tostring(d.delivery_id or ""))
      ok = true
    end
  end

  return ok and node.true_node or node.false_node
end

local function exec_goto(s, node)  return node.target_node_id end

local function exec_ens(s, node)
  local cfg_id = node.ens_configuration_id
  if not cfg_id or cfg_id == 0 then
    cfg_id = tonumber(s:getVariable(node.ens_config_var or "ens_configuration_id") or "")
  end
  if not cfg_id then
    freeswitch.consoleLog("ERR", "[ivr_executor] ens node: could not resolve configuration_id — skipping\n")
    return node.next
  end

  local caller_number = s:getVariable("caller_id_number") or ""

  -- Default recording_file_var to "recorded_file_path" so a preceding
  -- record_message node's output is forwarded without explicit config.
  local rfvar = (node.recording_file_var and node.recording_file_var ~= "") and node.recording_file_var or "recorded_file_path"
  local recording_file = s:getVariable(rfvar) or ""
  if recording_file == "" then recording_file = nil end

  -- ivr_number lets the backend refuse a configuration of another tenant: the ID can
  -- come from a session variable, which the publish-time tenant check never sees.
  local d = post("/ens/campaign/start-by-config", {
    configuration_id = cfg_id,
    recording_file   = recording_file,
    caller_number    = caller_number ~= "" and caller_number or nil,
    ivr_number       = CALL_NUMBER,
  })

  if d and d.success and d.campaign_id then
    s:setVariable("ens_notification_uuid", tostring(d.campaign_id))
    freeswitch.consoleLog("INFO",
      "[ivr_executor] ens node: campaign started id=" .. tostring(d.campaign_id) ..
      " destinations=" .. tostring(d.total_destinations or 0) .. "\n")
  else
    freeswitch.consoleLog("ERR",
      "[ivr_executor] ens node: blast failed — " .. tostring(d and d.error or "no response") .. "\n")
  end

  return node.next
end

local function exec_ers(s, node)
  local cfg_id = node.ers_configuration_id
  if not cfg_id or cfg_id == 0 then
    cfg_id = tonumber(s:getVariable(node.ers_config_var or "ers_configuration_id") or "")
  end
  if not cfg_id then
    freeswitch.consoleLog("ERR", "[ivr_executor] ers node: could not resolve configuration_id — hanging up\n")
    return nil
  end

  -- The API never echoes conference_room back — it is generated here and
  -- reused directly to bridge, matching the constraint the internal API
  -- enforces on the value it is given: ^[a-z0-9_]{1,64}$
  local room = "ers_" .. tostring(cfg_id) .. "_" .. tostring(os.time())

  local d = post("/ers/incidents", {
    configuration_id = cfg_id,
    caller_number    = s:getVariable("caller_id_number") or "",
    conference_room  = room,
    group_type       = node.group_type or "primary",
  })

  if d and d.incident_uuid then
    s:setVariable("ers_incident_uuid", d.incident_uuid)
    s:execute("conference", room .. "@default")
    -- s:execute("conference", ...) blocks until THIS leg leaves the
    -- room. Reuse the already-built /ers/incidents/:uuid/complete
    -- endpoint (handles ers_queues promotion too — do not rebuild that
    -- here) so the incident row stops showing as permanently ACTIVE.
    -- NOTE: this marks "this leg left," not "the room is empty" — a
    -- room with other members still bridged stays live in FreeSWITCH
    -- regardless of this incident row's status; live occupancy must
    -- always be checked via ESL conference member count, never this
    -- status field alone.
    post("/ers/incidents/" .. d.incident_uuid .. "/complete", {
      recording_file = s:getVariable("recorded_file_path") or nil,
    })
  else
    freeswitch.consoleLog("ERR", "[ivr_executor] ers node: incident creation failed — " .. tostring(d and d.error or "no response") .. "\n")
  end
  return nil
end

local function exec_hangup(s, node)
  local src = node.goodbye_source_type or "none"
  if src == "audio" then
    local f = resolve_audio(node.play_audio_url)
    if f then
      s:streamFile(f)
    else
      freeswitch.consoleLog("ERR", "[ivr_executor] hangup: goodbye_source_type=audio but audio_url is missing/unresolvable (audio_url=" .. tostring(node.play_audio_url) .. ")\n")
    end
  elseif src == "tts" then
    local msg = node.goodbye_text or ""
    if msg ~= "" then speak(s, msg)
    else freeswitch.consoleLog("WARN", "[ivr_executor] hangup: goodbye_source_type=tts but goodbye_text is empty\n") end
  end
  s:hangup()
  return nil
end

local function exec_record_message(s, node)
  freeswitch.consoleLog("INFO", "[ivr_executor] record_message: started\n")

  -- Resolve recordings directory from FreeSWITCH runtime (never hardcode paths)
  -- recordings_dir is always set by FreeSWITCH's built-in default_vars.conf.xml
  local rec_base = _api:execute("global_getvar", "recordings_dir")
  if not rec_base or rec_base == "" then
    rec_base = "/var/lib/freeswitch/recordings"
  end
  local rec_dir = rec_base .. "/ivr"
  freeswitch.consoleLog("DEBUG", "[ivr_executor] record_message: rec_dir=" .. rec_dir .. "\n")

  -- Auto-create IVR recording directory (deploymentEngine creates at deploy time;
  -- this handles fresh installs or directory removal without redeployment)
  os.execute("mkdir -p '" .. rec_dir .. "'")

  -- Unique filename: ivr_<call-uuid>_<unix-timestamp>.wav (no collisions)
  local call_uuid = s:getVariable("uuid") or "unknown"
  local fpath = rec_dir .. "/ivr_" .. call_uuid .. "_" .. os.time() .. ".wav"
  freeswitch.consoleLog("INFO", "[ivr_executor] record_message: path=" .. fpath .. "\n")

  -- Play prompt before recording — selected source is used exclusively, no cross-type fallback.
  local src = node.prompt_source_type or "tts"
  if src == "audio" then
    local pf = resolve_audio(node.prompt_audio_url)
    if pf and pf ~= "" then
      freeswitch.consoleLog("INFO", "[ivr_executor] record_message: playing prompt file\n")
      s:streamFile(pf)
    else
      freeswitch.consoleLog("ERR", "[ivr_executor] record_message: prompt_source_type=audio but audio_url is missing/unresolvable (audio_url=" .. tostring(node.prompt_audio_url) .. ")\n")
    end
  elseif node.prompt_text and node.prompt_text ~= "" then
    freeswitch.consoleLog("INFO", "[ivr_executor] record_message: speaking prompt (TTS)\n")
    speak(s, interp(s, node.prompt_text))
  end

  -- Abort if caller disconnected during prompt playback
  if not s:ready() then
    freeswitch.consoleLog("WARN", "[ivr_executor] record_message: caller disconnected before recording\n")
    return nil
  end

  -- Play beep — always, gives caller a clear start signal
  s:execute("playback", "tone_stream://%(500,0,640)")
  s:sleep(100)

  -- Record audio — stops when caller presses the stop key, silence is detected,
  -- or max_sec is reached. dtmf_stop_key defaults to "#"; empty string = no DTMF stop.
  -- Empty string is truthy in Lua, so we must compare to nil to detect "not set".
  local max_sec  = node.max_seconds       or 60
  local sil_thr  = node.silence_threshold or 500
  -- silence_hits: consecutive 20 ms frames that must be silent before auto-stop.
  -- Default 20 ≈ 400 ms of silence after speech ends (old default of 3 = 60 ms was too short).
  local sil_hits = node.silence_hits      or 20
  local stop_key = (node.dtmf_stop_key ~= nil) and node.dtmf_stop_key or "#"

  -- The record app's input callback (on_dtmf in mod_dptools.c) reads the channel
  -- variable "playback_terminators" to decide which DTMF digits stop recording.
  -- The record function only parses 4 args (path, max_sec, sil_thr, sil_hits) —
  -- a 5th positional terminator arg is silently ignored on this FreeSWITCH build.
  -- After recording, "playback_terminator_used" is set to the digit that stopped it.
  local dtmf_stopped = false
  if stop_key ~= "" then
    s:execute("set", "playback_terminators=" .. stop_key)
  else
    s:execute("set", "playback_terminators=none")
  end

  freeswitch.consoleLog("INFO",
    "[ivr_executor] record_message: recording max_sec=" .. max_sec ..
    " sil_thr=" .. sil_thr .. " sil_hits=" .. sil_hits ..
    " stop_key='" .. stop_key .. "'\n")

  s:execute("record", fpath .. " " .. max_sec .. " " .. sil_thr .. " " .. sil_hits)

  -- Check which digit stopped the recording (empty if silence/max_sec).
  local term_used = s:getVariable("playback_terminator_used") or ""
  if stop_key ~= "" and term_used ~= "" then
    dtmf_stopped = true
  end
  -- Restore to safe default so subsequent playback is not accidentally terminated.
  s:execute("set", "playback_terminators=none")

  if dtmf_stopped then
    freeswitch.consoleLog("INFO",
      "[ivr_executor] record_message: stopped by DTMF '" .. term_used .. "' (playback_terminators)\n")
  else
    freeswitch.consoleLog("INFO",
      "[ivr_executor] record_message: stopped by silence or max duration\n")
  end
  s:sleep(200)

  -- Handle caller hangup during recording
  if not s:ready() then
    freeswitch.consoleLog("WARN", "[ivr_executor] record_message: caller disconnected during recording\n")
    return nil
  end

  -- Verify recording has meaningful audio content (guards against silence-only captures)
  local rec_size = 0
  local fh = io.open(fpath, "rb")
  if fh then
    rec_size = fh:seek("end") or 0
    fh:close()
  end
  freeswitch.consoleLog("INFO",
    "[ivr_executor] record_message: file=" .. fpath .. " bytes=" .. rec_size .. "\n")

  if rec_size < 2000 then
    freeswitch.consoleLog("ERR",
      "[ivr_executor] record_message: recording too short or empty (bytes=" .. rec_size ..
      ") — not proceeding to next node\n")
    speak(s, "We could not capture your recording. Please try again.")
    return nil
  end

  -- Store file path in session variable — downstream ENS node reads this
  local var_name = node.variable_name or "recorded_file_path"
  set_var(s, var_name, fpath)
  freeswitch.consoleLog("INFO",
    "[ivr_executor] record_message: stored " .. var_name .. "=" .. fpath .. "\n")

  -- Register the recording with the backend immediately so tenant_id is
  -- derived from emergency_numbers (not inferred later at boot-scan time
  -- where the only fallback is the first tenant in the DB).
  local reg_number = s:getVariable("destination_number") or ""
  if reg_number ~= "" then
    post("/ivr/recording/register", { recording_path = fpath, number = reg_number })
    freeswitch.consoleLog("INFO",
      "[ivr_executor] record_message: registration sent for number=" .. reg_number .. "\n")
  else
    freeswitch.consoleLog("WARN",
      "[ivr_executor] record_message: destination_number not set — skipping registration\n")
  end

  freeswitch.consoleLog("INFO", "[ivr_executor] record_message: completed, proceeding to next node\n")
  return node.next
end

local function exec_set_variable(s, node)
  set_var(s, node.variable or "unknown_var", interp(s, node.value) or "")
  return node.next
end

local function exec_transfer(s, node)
  local raw = node.destination or ""
  local dest = interp(s, raw) or ""
  local dialplan = node.dialplan or "XML"
  local context = node.context or "default"
  -- The transfer argument is "<dest> <dialplan> <context>", split on whitespace. Words the
  -- flow author wrote (e.g. "1001 XML public") work as before; a substituted VALUE that adds
  -- a word (e.g. a caller name "1000 inline") would inject a dialplan, so that is refused.
  local function words(v) local n = 0; for _ in v:gmatch("%S+") do n = n + 1 end; return n end
  if words(dest) > words((raw:gsub("${[^}]+}", "x"))) then
    freeswitch.consoleLog("ERR", "[ivr_executor] transfer: a variable value added a word to the destination — refused\n")
    error("transfer destination not allowed")
  end
  -- The inline dialplan runs arbitrary applications. Publishing a NEW inline transfer is
  -- refused; flows already published keep working unless the operator sets the global
  -- variable ENRS_IVR_BLOCK_INLINE_TRANSFER=true (see scripts/ivr-compat-report.js).
  -- A destination's own second word is the dialplan the engine uses, so it counts too.
  local dest_dp = dest:match("^%s*%S+%s+(%S+)")
  if dialplan:lower() == "inline" or (dest_dp and dest_dp:lower() == "inline") then
    if (_api:execute("global_getvar", "ENRS_IVR_BLOCK_INLINE_TRANSFER") or "") == "true" then
      freeswitch.consoleLog("ERR", "[ivr_executor] transfer: inline dialplan blocked by ENRS_IVR_BLOCK_INLINE_TRANSFER\n")
      error("transfer dialplan not allowed")
    end
    freeswitch.consoleLog("WARN", "[ivr_executor] transfer: inline dialplan used (deprecated; republish with XML)\n")
  end
  s:execute("transfer", no_api_expand(dest) .. " " .. dialplan .. " " .. context)
  return nil
end

local function exec_webhook(s, node)
  local url = interp(s, node.url) or ""
  if url == "" then
    freeswitch.consoleLog("ERR", "[ivr_executor] webhook node: empty url — skipping\n")
    return node.next
  end
  -- Fire-and-forget to an arbitrary external URL — deliberately NOT routed
  -- through API_BASE/API_KEY (those are for this app's own internal API
  -- only). Same curl-via-io.popen pattern as every other HTTP call in this
  -- file, just without the internal auth header.
  -- IVR-14: the URL is escaped for the shell like the body (a quote in it used to end
  -- the shell word and run commands), and passed with --url so a value starting with
  -- "-" cannot be read as a curl option. The request itself is unchanged.
  local body = interp(s, node.body_template) or "{}"
  local safe_body = body:gsub("'", "'\\''")
  local safe_url = url:gsub("'", "'\\''")
  local cmd = string.format(
    "curl -s -m %d -X POST -H 'Content-Type: application/json' -d '%s' --url '%s' 2>/dev/null",
    HTTP_TIMEOUT, safe_body, safe_url)
  local h = io.popen(cmd)
  if h then h:close() end
  return node.next
end

local function exec_rest_api(s, node)
  local br = node.branches or {}
  local url = interp(s, node.url) or ""
  if url == "" then
    freeswitch.consoleLog("ERR", "[ivr_executor] rest_api: empty url\n")
    return br["http_error"] or br["_default"]
  end
  -- Interpolate URL/headers/body from channel vars (reuses interp()). The backend
  -- proxy holds the credential and applies auth — Lua never sees a secret.
  local tmo = tonumber(node.timeout_seconds) or 10
  if tmo < 1 then tmo = 1 end
  if tmo > 15 then tmo = 15 end
  local resp = internal_post_t("/ivr/rest-call", {
    credential_name   = node.credential_name,
    auth_type         = node.auth_type,
    auth_param_name   = node.auth_param_name,
    method            = node.method or "GET",
    url               = url,
    headers           = interp(s, node.headers_template or ""),
    body              = interp(s, node.body_template or ""),
    timeout_seconds   = tmo,
    response_mappings = node.response_mappings,
    ivr_number        = CALL_NUMBER,
  }, tmo + 5)
  if resp == nil then
    -- Proxy unreachable or internal curl timed out. Not the external system's
    -- fault per se, but there is no usable response — route http_error.
    freeswitch.consoleLog("ERR", "[ivr_executor] rest_api: no response from proxy\n")
    return br["http_error"] or br["_default"]
  end
  -- Apply server-computed mappings (names → values). NEVER log the values (O-7).
  if type(resp.vars) == "table" then
    for k, v in pairs(resp.vars) do set_var(s, k, tostring(v)) end
  end
  local outcome = resp.outcome or "http_error"
  freeswitch.consoleLog("INFO", "[ivr_executor] rest_api: status=" .. tostring(resp.status) .. " outcome=" .. outcome .. "\n")
  return br[outcome] or br["_default"]
end

-- Queue Eligibility — point-in-time snapshot (NOT a guarantee; no agent is
-- reserved). Calls the backend, which runs the 3 read-only callcenter lists and
-- joins tier membership with agent status/state. FAILS CLOSED: on any backend/
-- parse/ESL error (nil response, missing reason) the node routes CHECK_ERROR and
-- never ELIGIBLE. This node never transfers — wire ELIGIBLE to a Transfer node.
local function exec_queue_eligibility(s, node)
  local br = node.branches or {}
  local queue = interp(s, node.queue) or ""
  if queue == "" then
    freeswitch.consoleLog("ERR", "[ivr_executor] queue_eligibility: empty queue — fail closed\n")
    return br["CHECK_ERROR"] or br["_default"]
  end
  local tmo = tonumber(node.timeout_seconds) or 5
  if tmo < 1 then tmo = 1 end
  if tmo > 15 then tmo = 15 end
  local resp = internal_post_t("/ivr/queue-eligibility", { queue = queue }, tmo + 2)
  if resp == nil or resp.reason == nil then
    freeswitch.consoleLog("ERR", "[ivr_executor] queue_eligibility: no/invalid response — fail closed\n")
    return br["CHECK_ERROR"] or br["_default"]
  end
  -- Expose snapshot counters for downstream Condition nodes (never secrets).
  s:setVariable("queue_elig_reason",    tostring(resp.reason))
  s:setVariable("queue_elig_available", tostring(resp.available or 0))
  s:setVariable("queue_elig_members",   tostring(resp.members or 0))
  freeswitch.consoleLog("INFO",
    "[ivr_executor] queue_eligibility queue=" .. queue .. " reason=" .. tostring(resp.reason)
    .. " available=" .. tostring(resp.available or 0) .. "\n")
  return br[resp.reason] or br["_default"]
end

-- Queue Wait — bounded pre-transfer eligibility wait. Polls the SAME read-only
-- eligibility endpoint as queue_eligibility; adds hold audio + optional periodic
-- announcement + an ABSOLUTE deadline. Fails closed (CHECK_ERROR) on any check
-- failure and never treats a failed check as "no agents". NEVER transfers.
local function exec_queue_wait(s, node)
  local br = node.branches or {}
  local queue = interp(s, node.queue) or ""
  if queue == "" then
    freeswitch.consoleLog("ERR", "[ivr_executor] queue_wait: empty queue — fail closed\n")
    return br["CHECK_ERROR"] or br["_default"]
  end
  local max_wait = tonumber(node.max_wait_seconds) or 0
  if max_wait < 1 then max_wait = 1 end
  local interval = tonumber(node.recheck_interval_seconds) or 5
  if interval < 1 then interval = 1 end
  local chk_tmo = tonumber(node.check_timeout_seconds) or 5
  if chk_tmo < 1 then chk_tmo = 1 end
  if chk_tmo > 15 then chk_tmo = 15 end
  local ann_every = tonumber(node.announcement_every_seconds) or 0

  -- Deadline computed ONCE. os.time() (wall-clock seconds) is the elapsed-time
  -- source already used by the executor; 1s granularity is adequate here.
  local start    = os.time()
  local deadline = start + max_wait
  local last_ann = 0   -- seconds-since-start of the last announcement (0 => none yet; first only after ann_every)

  while s:ready() and os.time() < deadline do
    -- 1) One eligibility snapshot (reuses the read-only endpoint; fail closed).
    local resp = internal_post_t("/ivr/queue-eligibility", { queue = queue }, chk_tmo + 2)
    if resp == nil or resp.reason == nil then
      freeswitch.consoleLog("ERR", "[ivr_executor] queue_wait: eligibility check failed for queue=" .. queue .. " — CHECK_ERROR\n")
      return br["CHECK_ERROR"] or br["_default"]
    end
    if resp.reason == "ELIGIBLE" then
      s:setVariable("queue_wait_reason", "ELIGIBLE")
      s:setVariable("queue_wait_elapsed", tostring(os.time() - start))
      freeswitch.consoleLog("INFO", "[ivr_executor] queue_wait: ELIGIBLE queue=" .. queue .. " after " .. tostring(os.time() - start) .. "s\n")
      return br["ELIGIBLE"] or br["_default"]
    end
    -- Per-reason BUSINESS POLICY (admin-configurable). Recoverable reasons
    -- default to "wait"; structural reasons (no_members/queue_not_found) are
    -- 'error'|'overflow' in new nodes but an ABSENT policy field (legacy graph)
    -- falls back to "wait" to preserve the original behaviour. An unexpected /
    -- unknown reason fails closed to CHECK_ERROR — never waits as if merely busy.
    --
    -- policy_pick(): absent (nil) field → "wait" (legacy preserve, for BOTH
    -- recoverable and structural). A present-but-INVALID value (empty string,
    -- unknown string, non-string) is coerced to the per-field SAFE default, so a
    -- corrupt/imported structural value can never silently degrade to an
    -- indefinite "wait" — it goes to "error". Published graphs can't carry an
    -- invalid value (Zod enum), so this only shields non-validated/imported ones.
    local function policy_pick(v, a1, a2, safe_default)
      if v == nil then return "wait" end          -- legacy/absent → preserve original wait
      if type(v) ~= "string" then return safe_default end
      if v == a1 or v == a2 then return v end     -- valid enum value → honour it
      return safe_default                         -- present-but-invalid → safe default
    end
    local reason = resp.reason
    local action
    if     reason == "NO_AVAILABLE_AGENTS"  then action = policy_pick(node.policy_no_available_agents, "wait",  "overflow", "wait")
    elseif reason == "ALL_AGENTS_PAUSED"    then action = policy_pick(node.policy_all_agents_paused,    "wait",  "overflow", "wait")
    elseif reason == "NO_AGENTS_LOGGED_IN"  then action = policy_pick(node.policy_no_agents_logged_in,  "wait",  "overflow", "wait")
    elseif reason == "NO_MEMBERS"           then action = policy_pick(node.policy_no_members,            "error", "overflow", "error")
    elseif reason == "QUEUE_NOT_FOUND"      then action = policy_pick(node.policy_queue_not_found,       "error", "overflow", "error")
    else                                         action = "error" end
    if action == "overflow" then
      s:setVariable("queue_wait_reason", reason .. ":OVERFLOW")
      freeswitch.consoleLog("INFO", "[ivr_executor] queue_wait: reason=" .. reason .. " policy=overflow → OVERFLOW\n")
      return br["OVERFLOW"] or br["_default"]
    elseif action == "error" then
      s:setVariable("queue_wait_reason", reason .. ":CHECK_ERROR")
      freeswitch.consoleLog("ERR", "[ivr_executor] queue_wait: reason=" .. reason .. " policy=error → CHECK_ERROR\n")
      return br["CHECK_ERROR"] or br["_default"]
    end
    -- action == "wait": keep holding until eligible or the deadline.
    -- Deadline precedence: if the check consumed the remaining time, do NOT
    -- start another cycle (no announcement, no hold) — fall out to OVERFLOW.
    if not s:ready() or os.time() >= deadline then break end

    -- 2) Optional periodic announcement (never at t=0; only once cadence elapsed).
    if ann_every > 0 then
      local elapsed = os.time() - start
      if elapsed - last_ann >= ann_every then
        play_prompt(s, node.announcement_source_type, node.announcement_audio_url, node.announcement_text)
        last_ann = elapsed
        if not s:ready() or os.time() >= deadline then break end
      end
    end

    -- 3) Finite hold chunk (never a looping MOH stream), capped at the time left.
    local remaining = deadline - os.time()
    if remaining <= 0 then break end
    local chunk = interval
    if chunk > remaining then chunk = remaining end
    local hsrc = node.hold_source_type or "none"
    if hsrc == "audio" then
      local hf = resolve_audio(node.hold_audio_url)
      if hf then s:streamFile(hf) else s:execute("playback", "silence_stream://" .. (chunk * 1000)) end
    elseif hsrc == "tts" then
      local ht = interp(s, node.hold_prompt_text)
      if ht ~= "" then speak(s, ht) else s:execute("playback", "silence_stream://" .. (chunk * 1000)) end
    else
      s:execute("playback", "silence_stream://" .. (chunk * 1000))
    end
  end

  -- Caller gone → end quietly; otherwise the absolute deadline expired → OVERFLOW once.
  if not s:ready() then return nil end
  s:setVariable("queue_wait_reason", "OVERFLOW")
  freeswitch.consoleLog("INFO", "[ivr_executor] queue_wait: deadline reached (" .. max_wait .. "s) queue=" .. queue .. " — OVERFLOW\n")
  return br["OVERFLOW"] or br["_default"]
end

local function exec_ers_ring_all(s, node)
  local cfg_id = node.ers_configuration_id
  if not cfg_id then
    freeswitch.consoleLog("ERR", "[ivr_executor] ers_ring_all: missing ers_configuration_id — hanging up\n")
    speak(s, "This emergency service is not configured. Please call emergency services directly.")
    s:hangup("NORMAL_CLEARING")
    return nil
  end

  local d = post("/ers/ring-all", {
    configuration_id = cfg_id,
    tier             = node.tier or "primary",
    caller_number    = s:getVariable("caller_id_number") or "",
    caller_name      = s:getVariable("caller_id_name") or nil,
    emergency_number = s:getVariable("destination_number") or nil,
  })

  -- d.success == false means the backend rejected the request (e.g. no
  -- responders configured). Never fail silently — log ERR with the reason
  -- and play an audible fallback so the caller is not left in silence.
  if not d or not d.success then
    local reason = (d and d.reason) or "no_response"
    local err_detail = (d and d.error) or "no response from backend"
    freeswitch.consoleLog("ERR",
      "[ivr_executor] ers_ring_all: ring-all failed — reason=" .. reason ..
      " detail=" .. err_detail .. "\n")
    if reason == "no_responders" then
      speak(s, "No emergency responders are currently configured for this service. Please call emergency services directly.")
    else
      speak(s, "The emergency response service is currently unavailable. Please call emergency services directly.")
    end
    s:hangup("NORMAL_CLEARING")
    return nil
  end

  if d.conference_room then
    s:setVariable("ers_incident_uuid", d.incident_uuid or "")
    -- Blocks until THIS leg leaves. The backend ring loop keeps re-ringing
    -- responders in parallel the whole time the caller waits in the room.
    s:execute("conference", d.conference_room .. "@default")
    if d.incident_uuid then
      post("/ers/incidents/" .. d.incident_uuid .. "/complete", {})
    end
  end
  return nil
end

local function exec_ers_overflow_check(s, node)
  local br = node.branches or {}
  local d = get("/ers/tier-status?configuration_id=" .. tostring(node.ers_configuration_id or 0))
  if not d or not d.success then
    freeswitch.consoleLog("ERR", "[ivr_executor] ers_overflow_check: tier-status failed — routing to full branch\n")
    return br["full"]
  end
  if d.primary and not d.primary.occupied then
    return br["primary"]
  elseif d.secondary and not d.secondary.occupied then
    return br["secondary"]
  end
  return br["full"]
end

local function exec_ers_overflow_wait(s, node)
  local enq = post("/ers/overflow/enqueue", {
    configuration_id   = node.ers_configuration_id or 0,
    caller_number      = s:getVariable("caller_id_number") or "",
    caller_name        = s:getVariable("caller_id_name") or nil,
    destination_number = s:getVariable("destination_number") or nil,
  })
  if not enq or not enq.queue_id then
    freeswitch.consoleLog("ERR", "[ivr_executor] ers_overflow_wait: enqueue failed — falling back\n")
    return node.next
  end

  local hold_src = node.hold_source_type or "tts"
  if hold_src == "audio" then
    local hold_file = resolve_audio(node.hold_audio_url)
    if hold_file then
      s:streamFile(hold_file)
    else
      freeswitch.consoleLog("ERR", "[ivr_executor] ers_overflow_wait: hold_source_type=audio but audio_url is missing/unresolvable (audio_url=" .. tostring(node.hold_audio_url) .. ")\n")
    end
  else
    local hold_text = interp(s, node.hold_prompt_text)
    if hold_text ~= "" then speak(s, hold_text) end
  end

  local max_wait = node.max_wait_seconds or 300
  local deadline = os.time() + max_wait

  while s:ready() and os.time() < deadline do
    local d = get("/ers/overflow/poll?queue_id=" .. tostring(enq.queue_id))
    if d and d.ready and d.conference_room then
      s:execute("conference", d.conference_room .. "@default")
      if d.incident_uuid then
        post("/ers/incidents/" .. d.incident_uuid .. "/complete", {})
      end
      return nil
    end
    if d and d.cancelled then return node.next end
    -- brief hold-tone loop between polls
    s:execute("playback", "silence_stream://3000")
  end

  return node.next
end

local function exec_ens_blast_record(s, node)
  local dest = s:getVariable("destination_number") or ""

  -- PIN gate — /ens/verify-pin is the single source of truth (handles the
  -- "no PIN configured -> always authorized" case internally).
  local authorized = false
  local pin_src = node.pin_prompt_source_type or "tts"
  for attempt = 1, 3 do
    if pin_src == "audio" then
      local pin_audio = resolve_audio(node.pin_prompt_audio_url)
      if pin_audio then
        s:streamFile(pin_audio)
      else
        freeswitch.consoleLog("ERR", "[ivr_executor] ens_blast_record: pin_prompt_source_type=audio but audio_url is missing/unresolvable (audio_url=" .. tostring(node.pin_prompt_audio_url) .. ")\n")
      end
    else
      local prompt = interp(s, node.pin_prompt_text)
      if prompt == "" then prompt = "Please enter your authorization PIN followed by pound." end
      speak(s, prompt)
    end
    local pin = s:getDigits(8, "#", 10000)
    local verify = post("/ens/verify-pin", { trigger_number = dest, pin = pin or "" })
    if verify and verify.authorized then
      authorized = true
      break
    end
    speak(s, "Invalid PIN.")
  end
  if not authorized then
    speak(s, "Maximum authorization attempts exceeded. Goodbye.")
    s:hangup("CALL_REJECTED")
    return nil
  end

  -- Resolve configuration_id (node value, else lookup by dialed number)
  local cfg_id = node.ens_configuration_id
  if not cfg_id then
    local lookup = get("/ens/lookup?number=" .. url_encode(dest) .. "&ivr_number=" .. url_encode(CALL_NUMBER))
    if lookup and lookup.success and lookup.data then
      cfg_id = lookup.data.configuration_id
    end
  end
  if not cfg_id then
    freeswitch.consoleLog("ERR", "[ivr_executor] ens_blast_record: could not resolve configuration_id\n")
    speak(s, "This notification service is not configured. Goodbye.")
    return nil
  end

  -- Record the initiator's message.
  -- execute("record") is used, not the Lua session recording API, because only the
  -- application variant supports a DTMF stop key (5th positional argument).
  -- The session API always runs until duration/silence regardless of keys pressed.
  local rec_dir = _api:execute("global_getvar", "recordings_dir") or "/var/lib/freeswitch/recordings"
  local fpath = rec_dir .. "/ens/ens_" .. tostring(cfg_id) .. "_" .. os.time() .. ".wav"
  os.execute("mkdir -p '" .. rec_dir .. "/ens'")
  local rec_src = node.record_prompt_source_type or "tts"
  if rec_src == "audio" then
    local rec_audio = resolve_audio(node.record_prompt_audio_url)
    if rec_audio then
      s:streamFile(rec_audio)
    else
      freeswitch.consoleLog("ERR", "[ivr_executor] ens_blast_record: record_prompt_source_type=audio but audio_url is missing/unresolvable (audio_url=" .. tostring(node.record_prompt_audio_url) .. ")\n")
    end
  else
    local rprompt = interp(s, node.record_prompt_text)
    if rprompt == "" then rprompt = "Record your emergency message after the tone. Press pound when finished." end
    speak(s, rprompt)
  end
  s:execute("playback", "tone_stream://%(500,0,640)")
  local max_rec  = node.max_record_seconds or 120
  local sil_thr  = node.silence_threshold  or 500
  local sil_hits = node.silence_hits        or 3
  s:execute("record", fpath .. " " .. max_rec .. " " .. sil_thr .. " " .. sil_hits .. " #")

  -- Broadcast — reaches every contact's extension AND mobile (see
  -- resolveEnsContacts in ensInternalController.js).
  local d = post("/ens/notifications", {
    configuration_id = cfg_id,
    triggered_via    = "PHONE",
    caller_number    = s:getVariable("caller_id_number") or nil,
    recording_file   = fpath,
  })

  if d and d.notification_uuid then
    s:setVariable("ens_notification_uuid", d.notification_uuid)
    speak(s, "Your emergency notification is now being sent to all contacts.")
  else
    freeswitch.consoleLog("ERR", "[ivr_executor] ens_blast_record: blast failed — " .. tostring(d and d.error or "no response") .. "\n")
    speak(s, "There was a problem starting your notification. Please contact your administrator.")
  end

  return node.next
end

-- Play an ENS announcement using source_type from the ENS configuration.
-- source_type=="audio": play resolved media file.
--   If the URL is missing/unresolvable (configuration error): log ERR,
--   speak a hardcoded system error string. Do NOT speak the configured
--   TTS text — that is the TTS-selected content, not a fallback for audio.
-- source_type=="tts":  speak configured text; use fallback_text if empty.
--   Never switches to audio.
-- No cross-type fallback in either direction.
local function ens_announce(s, source_type, audio_url, text, fallback_text)
  local st = source_type or "tts"
  if st == "audio" then
    local resolved = audio_url and resolve_audio(audio_url)
    if resolved then
      s:execute("playback", resolved)
    else
      freeswitch.consoleLog("ERR",
        "[ivr_executor] ens_playback: source_type=audio but audio_url is missing/unresolvable" ..
        " (audio_url=" .. tostring(audio_url) .. ") — announcement cannot be played\n")
      speak(s, "An announcement is not available. Please contact your administrator.")
    end
  else
    -- source_type == "tts" (or unset)
    local msg = (text and text ~= "") and text or fallback_text
    if msg and msg ~= "" then
      speak(s, msg)
    else
      freeswitch.consoleLog("WARN",
        "[ivr_executor] ens_playback: source_type=tts but no text configured and no fallback\n")
    end
  end
end

local function exec_ens_playback(s, node)
  local br     = node.branches or {}
  local dest   = s:getVariable("destination_number") or ""
  local caller = s:getVariable("caller_id_number")   or ""

  -- 1. Resolve ENS configuration from the inbound emergency number.
  --    All announcement source_type/audio_url fields come from the ENS
  --    configuration, keyed by inbound number — guaranteed per-config isolation.
  local lookup = get("/ens/lookup?number=" .. url_encode(dest) .. "&ivr_number=" .. url_encode(CALL_NUMBER))
  if not lookup or not lookup.success or not lookup.data then
    freeswitch.consoleLog("ERR", "[ivr_executor] ens_playback: lookup failed for number=" .. dest .. "\n")
    speak(s, "This playback number is not configured. Please contact your system administrator.")
    return br["unauthorized"]
  end

  local cfg    = lookup.data
  local cfg_id = tostring(cfg.configuration_id or "")

  -- 2. Authorize caller and fetch latest campaign (scoped to this ENS config only).
  local latest = get("/ens/campaigns/latest?configuration_id=" .. url_encode(cfg_id) ..
                     "&caller=" .. url_encode(caller))

  if not latest then
    freeswitch.consoleLog("ERR", "[ivr_executor] ens_playback: no response from campaigns/latest config=" .. cfg_id .. "\n")
    ens_announce(s,
      cfg.no_pending_source_type, cfg.no_pending_audio_url, cfg.no_pending_msg,
      "There are no pending emergency notifications at this time.")
    return br["no_campaign"]
  end

  -- 3. Route by authorization state, playing the per-ENS-config announcement.
  if latest.authorized == false or latest.status == "UNAUTHORIZED" then
    freeswitch.consoleLog("INFO", "[ivr_executor] ens_playback: unauthorized caller=" .. caller .. " config=" .. cfg_id .. "\n")
    ens_announce(s,
      cfg.unauthorized_source_type, cfg.unauthorized_audio_url, cfg.unauthorized_msg,
      "You are not authorized to access this message.")
    return br["unauthorized"]
  end

  if latest.status == "NO_CAMPAIGN" then
    freeswitch.consoleLog("INFO", "[ivr_executor] ens_playback: no campaign caller=" .. caller .. " config=" .. cfg_id .. "\n")
    ens_announce(s,
      cfg.no_pending_source_type, cfg.no_pending_audio_url, cfg.no_pending_msg,
      "There are no pending emergency notifications at this time.")
    return br["no_campaign"]
  end

  if latest.status == "EXPIRED" then
    freeswitch.consoleLog("INFO", "[ivr_executor] ens_playback: expired campaign caller=" .. caller .. " config=" .. cfg_id .. "\n")
    ens_announce(s,
      cfg.expiry_source_type, cfg.expiry_audio_url, cfg.expiry_announcement,
      "This emergency notification has expired.")
    return br["expired"]
  end

  if latest.status == "ACTIVE" then
    -- The campaign audio is stored in ens_campaigns (recording_file or message_audio_url).
    -- This is distinct from the ENS-config announcement audio: it is whatever was
    -- recorded or uploaded when the blast was created, not a node config field.
    local audio_file = nil
    if latest.source_type == "recording" and latest.recording_file then
      audio_file = latest.recording_file
    elseif latest.source_type == "url" and latest.message_audio_url then
      audio_file = latest.message_audio_url
    end

    if audio_file then
      s:execute("playback", no_api_expand(audio_file))
      get("/ens/campaigns/" .. url_encode(tostring(latest.campaign_id or "")) ..
          "/playback-log?caller=" .. url_encode(caller))
    else
      freeswitch.consoleLog("ERR", "[ivr_executor] ens_playback: ACTIVE campaign has no audio — campaign_id=" .. tostring(latest.campaign_id) .. " config=" .. cfg_id .. "\n")
      ens_announce(s,
        cfg.no_pending_source_type, cfg.no_pending_audio_url, cfg.no_pending_msg,
        "There are no pending emergency notifications at this time.")
    end
    return br["active"]
  end

  freeswitch.consoleLog("WARN", "[ivr_executor] ens_playback: unexpected status=" .. tostring(latest.status) .. " config=" .. cfg_id .. "\n")
  return br["no_campaign"]
end

-- ── Executor dispatch table ───────────────────────────────────────
-- NOTE: "goto" is a reserved word since Lua 5.2 and cannot be used as
-- a bare table-constructor key (`goto = fn` is a syntax error) — it
-- must be written as a string-indexed key.

local EXEC = {
  play           = exec_play,
  say            = exec_say,
  gather         = exec_gather,
  condition      = exec_condition,
  ["goto"]       = exec_goto,
  ens            = exec_ens,
  ers            = exec_ers,
  hangup         = exec_hangup,
  record_message = exec_record_message,
  set_variable   = exec_set_variable,
  transfer       = exec_transfer,
  webhook        = exec_webhook,
  rest_api       = exec_rest_api,
  queue_eligibility = exec_queue_eligibility,
  queue_wait     = exec_queue_wait,
  ers_ring_all   = exec_ers_ring_all,
  ers_overflow_check = exec_ers_overflow_check,
  ers_overflow_wait = exec_ers_overflow_wait,
  ens_blast_record = exec_ens_blast_record,
  ens_playback   = exec_ens_playback,
}

-- ── Main ─────────────────────────────────────────────────────────

if not session:ready() then return end

session:answer()
session:setAutoHangup(false)

local dest = session:getVariable("destination_number") or ""
CALL_NUMBER = dest
freeswitch.consoleLog("INFO", "[ivr_executor] Fetching IVR for number=" .. dest .. "\n")

-- FAILSAFE: play a local failsafe audio file (ENRS_FAILSAFE_PROMPT, optional)
-- then transfer to the operator fallback (ENRS_FAILSAFE_EXT). Hang up only if no
-- fallback is set. Used when no flow can be loaded and when a flow breaks.
local function enter_failsafe(cause)
  if not session:ready() then return end
  local fp = _api:execute("global_getvar", "ENRS_FAILSAFE_PROMPT") or ""
  if fp ~= "" and fp ~= "_undef_" then session:streamFile(fp) end
  local fx = _api:execute("global_getvar", "ENRS_FAILSAFE_EXT") or ""
  if fx ~= "" and fx ~= "_undef_" then
    freeswitch.consoleLog("WARN", "[ivr_executor] failsafe transfer to " .. fx .. "\n")
    session:execute("transfer", fx .. " XML default")
  else
    freeswitch.consoleLog("ERR", "[ivr_executor] ENRS_FAILSAFE_EXT not set — hanging up\n")
    session:hangup(cause or "NO_ROUTE_DESTINATION")
  end
end

-- entry_node_id and nodes are TOP-LEVEL fields on the lookup response,
-- not nested under a "graph" key. Short timeout so a slow/down backend fails
-- fast to the failsafe rather than leaving the caller in silence.
local data = get_t("/ivr/lookup?number=" .. url_encode(dest), LOOKUP_TIMEOUT)
if not data or not data.entry_node_id then
  freeswitch.consoleLog("ERR",
    "[ivr_executor] lookup failed/empty for number=" .. dest .. " — entering failsafe\n")
  enter_failsafe("NO_ROUTE_DESTINATION")
  return
end

local nodes  = data.nodes or {}
local cur_id = data.entry_node_id
local steps  = 0
-- A broken flow (missing node, unknown type, node error, step cap) hangs up, as it
-- always has. Setting the global variable ENRS_FAILSAFE_ON_FLOW_ERROR=true sends such
-- calls to the failsafe (ENRS_FAILSAFE_PROMPT, then ENRS_FAILSAFE_EXT) instead. Opt-in:
-- call routing does not change unless the operator enables it.
local broken = nil

while cur_id and steps < MAX_STEPS and session:ready() do
  steps = steps + 1
  local node = nodes[cur_id]
  if not node then
    freeswitch.consoleLog("ERR",
      "[ivr_executor] Node not found: " .. tostring(cur_id) .. "\n")
    broken = "node_not_found"
    break
  end
  local fn = EXEC[node.type]
  if not fn then
    freeswitch.consoleLog("WARN",
      "[ivr_executor] Unknown node type: " .. tostring(node.type) .. "\n")
    broken = "unknown_node_type"
    break
  end
  freeswitch.consoleLog("DEBUG",
    "[ivr_executor] step=" .. steps .. " node=" .. cur_id .. " type=" .. node.type .. "\n")
  local ok, next_id = pcall(fn, session, node)
  if not ok then
    freeswitch.consoleLog("ERR",
      "[ivr_executor] Error in node " .. cur_id .. ": " .. tostring(next_id) .. "\n")
    broken = "node_error"
    break
  end
  cur_id = next_id
end

if steps >= MAX_STEPS and cur_id then
  freeswitch.consoleLog("WARN",
    "[ivr_executor] MAX_STEPS (" .. MAX_STEPS .. ") reached for number=" .. dest .. "\n")
  broken = "max_steps"
end

local failsafe_on_error = (_api:execute("global_getvar", "ENRS_FAILSAFE_ON_FLOW_ERROR") or "") == "true"
if broken then
  freeswitch.consoleLog("ERR", "[ivr_executor] flow ended abnormally (" .. broken .. ") for number=" .. dest ..
    (failsafe_on_error and " — entering failsafe" or " — hanging up (ENRS_FAILSAFE_ON_FLOW_ERROR not set)") .. "\n")
end
if broken and failsafe_on_error then
  enter_failsafe("NORMAL_TEMPORARY_FAILURE")
  return   -- the failsafe transferred or hung up; never hang up a transferred call
end

if session:ready() then session:hangup() end